/**
 * HIGHFLY SF15 — eight hand-audited ORIGINAL Sim mechanics in one safe batch.
 * Not an autogenerated clone of the other 35 pending recipes.
 * Reuses frozen ClaudeCraft AbilityEffects at the actual HIGHFLY unlock levels.
 * Effects/targeting/forms/skills are tested in isolated no-deploy CI.
 */
import type {AbilityDef,AbilityEffect} from '../sim/types';
import {HIGHFLY_FUSED_SKILLS,type HighflyClass,type HighflyFusionSpec} from './sf3_skill_catalog';
type Registry=Record<string,AbilityDef>;
type Classes=Record<HighflyClass,{abilities:string[]}>;
export const SF15_IDS=[
 'hf_warrior_s4','hf_warrior_s5',
 'hf_paladin_s2','hf_paladin_s3',
 'hf_rogue_s1','hf_priest_s5','hf_druid_s5','hf_warlock_u2'
] as const;
function snapshot(d:AbilityDef,lv:number):AbilityEffect[]{
 let effects=d.effects;
 for(const rank of d.ranks??[])if(rank.level<=lv)effects=rank.effects;
 return effects.map(e=>({...e}));
}
function cost(d:AbilityDef,lv:number):number{
 let v=d.cost;for(const rank of d.ranks??[])if(rank.level<=lv)v=rank.cost;
 return v;
}
function levels(s:HighflyFusionSpec,d:AbilityDef[]):number[]{
 return [...new Set([s.unlockLevel,...d.flatMap(x=>(x.ranks??[])
    .filter(r=>r.level>s.unlockLevel&&r.level<=99).map(r=>r.level))])]
    .sort((a,b)=>a-b);
}
function check(d:AbilityDef|undefined,id:string,cls:HighflyClass):asserts d is AbilityDef{
 if(!d||d.id!==id||d.class!==cls||d.passive||d.hiddenFromPlayer)
  throw Error('SF15 missing or changed original source: '+id);
}
function type(e:AbilityEffect|undefined,k:AbilityEffect['type'],id:string):void{
 if(!e||e.type!==k)throw Error('SF15 donor mechanic drift '+id+': expected '+k);
}
function shrink<E extends AbilityEffect>(e:E,factor:number):E{
 const out={...e} as E & {min?:number;max?:number;bonus?:number;amount?:number;value?:number};
 for(const k of ['min','max','bonus','amount'] as const)
  if(typeof out[k]==='number') (out as Record<string,unknown>)[k]=
    Math.max(1,Math.round((out[k] as number)*factor));
 return out;
}
function effects(s:HighflyFusionSpec,ds:AbilityDef[],lv:number):AbilityEffect[]{
 const [a,b,c]=ds.map(d=>snapshot(d,lv));const id=s.id;
 if(id==='hf_warrior_s4'){
  if(a.length!==1||b.length!==1)throw Error('SF15 guard length');
  type(a[0],'selfBuff',id);type(b[0],'aoeDamage',id);
  if(a[0].type!=='selfBuff'||a[0].kind!=='buff_dr_phys'||
    b[0].type!=='aoeDamage'||b[0].frontal!==true)throw Error('SF15 guard source');
  return [a[0],shrink(b[0],.55)];
 }
 if(id==='hf_warrior_s5'){
  if(a.length!==2||b.length!==4)throw Error('SF15 fury shape');
  type(a[0],'aoeDamage',id);type(a[1],'selfBuff',id);
  if(a[1].type!=='selfBuff'||a[1].kind!=='aoe_echo')throw Error('SF15 echo');
  for(const e of b.slice(0,3))type(e,'weaponStrike',id);
  type(b[3],'enrageChance',id);
  if(b[3].type!=='enrageChance')throw Error('SF15 enrage');
  return [...a,...b.slice(0,3).map(e=>shrink(e,.22)),
   {...b[3],chance:Math.min(.5,b[3].chance),duration:Math.min(4,b[3].duration)}];
 }
 if(id==='hf_paladin_s2'){
  if(a.length!==2||b.length!==1)throw Error('SF15 disc shape');
  type(a[0],'directDamage',id);type(a[1],'chainDamage',id);
  type(b[0],'directDamage',id);
  if(a[0].type!=='directDamage'||b[0].type!=='directDamage')throw Error('SF15 disc');
  return [{...a[0],min:a[0].min+Math.round(b[0].min*.25),
   max:a[0].max+Math.round(b[0].max*.25)},a[1]];
 }
 if(id==='hf_paladin_s3'){
  if(a.length!==3||b.length!==1)throw Error('SF15 wall shape');
  type(a[0],'selfBuff',id);type(a[1],'absorb',id);
  type(a[2],'threatPulse',id);type(b[0],'buffTarget',id);
  if(b[0].type!=='buffTarget'||b[0].kind!=='buff_dr'||
   !b[0].party||a[1].type!=='absorb')throw Error('SF15 devotion contract');
  return [a[0],{...a[1],auraId:s.id+'_absorb'},a[2],b[0]];
 }
 if(id==='hf_rogue_s1'){
  if(a.length!==1||b.length!==1)throw Error('SF15 backstab shape');
  type(a[0],'weaponStrike',id);type(b[0],'weaponStrike',id);
  if(a[0].type!=='weaponStrike'||b[0].type!=='weaponStrike'||
    a[0].requiresBehind!==true||b[0].requiresBehind!==true)
     throw Error('SF15 positional strike changed');
  return [{...a[0],bonus:a[0].bonus+Math.round(b[0].bonus*.25),
    weaponMult:(a[0].weaponMult??1)+(b[0].weaponMult??1)*.18}];
 }
 if(id==='hf_priest_s5'){
  if(a.length!==2||b.length!==1)throw Error('SF15 nova shape');
  type(a[0],'aoeHeal',id);type(a[1],'aoeDamage',id);
  type(b[0],'buffTarget',id);
  if(b[0].type!=='buffTarget'||b[0].kind!=='heal_echo')throw Error('SF15 vigil');
  return [...a,{...b[0],value:Math.max(1,Math.round(b[0].value*.35)),
    duration:Math.min(b[0].duration,15)}];
 }
 if(id==='hf_druid_s5'){
  if(a.length!==1||b.length!==1||c.length!==1)throw Error('SF15 druid shape');
  for(const e of [a[0],b[0],c[0]])type(e,'selfBuff',id);
  if(a[0].type!=='selfBuff'||a[0].kind!=='form_travel'||
   b[0].type!=='selfBuff'||b[0].kind!=='buff_speed'||
   c[0].type!=='selfBuff'||c[0].kind!=='buff_armor_pct')
    throw Error('SF15 druid three forms mismatch');
  return [a[0],{...b[0],duration:Math.min(8,b[0].duration)},
   {...c[0],duration:Math.min(15,c[0].duration)}];
 }
 if(id==='hf_warlock_u2'){
  if(a.length!==1||b.length!==1)throw Error('SF15 legion shape');
  type(a[0],'armyOfDead',id);type(b[0],'summonUndead',id);
  if(a[0].type!=='armyOfDead'||b[0].type!=='summonUndead'||
   b[0].templateId!=='graveguard')throw Error('SF15 graveguard');
  return [...a,...b];
 }
 throw Error('SF15 unauthorized ability '+id);
}
function build(s:HighflyFusionSpec,donors:AbilityDef[]):AbilityDef{
 const [a,b,c]=donors;const id=s.id;
 const names=s.donors.join(',');
 const expected:Record<typeof SF15_IDS[number],string>={
  hf_warrior_s4:'raised_guard,revenge',
  hf_warrior_s5:'whirlwind,red_harvest',
  hf_paladin_s2:'sunward_disc,hammer_of_wrath',
  hf_paladin_s3:'holy_shield,devotion_ward',
  hf_rogue_s1:'backstab,ambush',
  hf_priest_s5:'holy_nova,seraphic_vigil',
  hf_druid_s5:'travel_form,dash,barkskin',
  hf_warlock_u2:'army_of_the_dead,raise_graveguard'
 };
 if(names!==expected[id as keyof typeof expected])throw Error('SF15 catalog donor mismatch '+id);
 if(id==='hf_warrior_s4'&&(!a.requiresShield||a.maxCharges!==2||!a.offGcd))
  throw Error('SF15 original Shield Guard requirements changed');
 if(id==='hf_paladin_s2'&&(!a.requiresShield||a.projectileFx!=='paladinSunwardDisc'||
   b.executeThreshold!==.2))throw Error('SF15 projectile/execute gate changed');
 if(id==='hf_rogue_s1'&&(a.awardsCombo!==1||b.awardsCombo!==1||!b.requiresStealth))
  throw Error('SF15 stealth donor mechanics changed');
 if(id==='hf_druid_s5'&&(!b.requiresForm||b.requiresForm!=='cat'||!c.usableInForm))
  throw Error('SF15 shapeshift source changed');
 if(id==='hf_warlock_u2'&&(a.school!=='shadow'||b.school!=='shadow'))
  throw Error('SF15 undead school changed');
 const snaps=levels(s,donors).map(lv=>({lv,fx:effects(s,donors,lv)}));
 const cooldown:Record<typeof SF15_IDS[number],number>={
  hf_warrior_s4:18,hf_warrior_s5:25,
  hf_paladin_s2:15,hf_paladin_s3:30,
  hf_rogue_s1:12,hf_priest_s5:25,hf_druid_s5:60,hf_warlock_u2:120
 };
 const overrides:Partial<AbilityDef>={
  specs:undefined,excludeSpecs:undefined,excludeSpecsAtLevel:undefined,
  hiddenFromPlayer:undefined,requiresQuest:undefined,actionReplacement:undefined,
  maxCharges:undefined,executeThreshold:undefined,
  cooldown:cooldown[id as keyof typeof cooldown],
  cost:id==='hf_warrior_s5'?80:cost(a,s.unlockLevel),
  description:'HIGHFLY SF15 — combinación auditada: '+s.name+' (donantes originales: '+
   s.donors.join(' + ')+'). Efectos nativos originales conservados, sin procs '+
   'especiales ligados a IDs originales. Ajuste de balance y VFX final pendientes.'
 };
 if(id==='hf_warrior_s4')Object.assign(overrides,{offGcd:undefined,threat:b.threat});
 if(id==='hf_warrior_s5')Object.assign(overrides,{cost:80});
 if(id==='hf_paladin_s2')Object.assign(overrides,{projectile:true,requiresShield:true,executeThreshold:undefined});
 if(id==='hf_paladin_s3')Object.assign(overrides,{exclusiveGroup:b.exclusiveGroup,offGcd:undefined});
 if(id==='hf_rogue_s1')Object.assign(overrides,{requiresStealth:undefined,awardsCombo:1});
 if(id==='hf_priest_s5')Object.assign(overrides,{targetType:undefined,requiresTarget:false});
 if(id==='hf_druid_s5')Object.assign(overrides,{offGcd:undefined,usableInForm:true});
 if(id==='hf_warlock_u2')Object.assign(overrides,{castTime:Math.max(a.castTime,b.castTime)});
 return {...a,...overrides,id,name:s.name,class:s.classId,
  learnLevel:s.unlockLevel,effects:snaps[0].fx,
  ranks:snaps.slice(1).map((x,i)=>({rank:i+2,level:x.lv,
    cost:id==='hf_warrior_s5'?80:cost(a,x.lv),effects:x.fx}))};
}
/** Fail atomically if any donor or class contract is missing. */
export function installSf15EightNative(abilities:Registry,classes:Classes):string[]{
 const catalog=Object.values(HIGHFLY_FUSED_SKILLS).flat();
 const staged:{id:string;cls:HighflyClass;def:AbilityDef}[]=[];
 for(const id of SF15_IDS){
  const s=catalog.find(x=>x.id===id);
  if(!s||!classes[s.classId]?.abilities||classes[s.classId].abilities.includes(id)||
   abilities[id])throw Error('SF15 missing/duplicate destination '+id);
  const ds=s.donors.map(x=>abilities[x]);
  for(let i=0;i<ds.length;i++)check(ds[i],s.donors[i],s.classId);
  staged.push({id,cls:s.classId,def:build(s,ds)});
 }
 if(staged.length!==8)throw Error('SF15 expected eight compatible hand adapters');
 for(const x of staged){abilities[x.id]=x.def;classes[x.cls].abilities.push(x.id);}
 return staged.map(x=>x.id);
}
